import{_ as o,o as a,c as t,a2 as d}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"Understanding UMM","description":"","frontmatter":{"title":"Understanding UMM","order":3},"headers":[],"relativePath":"learn/mod/umm.md","filePath":"learn/mod/umm.md","lastUpdated":1786943111000}'),n={name:"learn/mod/umm.md"};function r(s,e,i,l,c,h){return a(),t("div",null,[...e[0]||(e[0]=[d(`<h1 id="understanding-unitymodmanager-umm" tabindex="-1">Understanding UnityModManager (UMM) <a class="header-anchor" href="#understanding-unitymodmanager-umm" aria-label="Permalink to &quot;Understanding UnityModManager (UMM)&quot;">​</a></h1><p>Before writing your first Mod, let&#39;s understand how UMM &quot;plugs&quot; Mods into the game.</p><h2 id="what-is-umm" tabindex="-1">What is UMM <a class="header-anchor" href="#what-is-umm" aria-label="Permalink to &quot;What is UMM&quot;">​</a></h2><p><strong>UnityModManager</strong> is a general-purpose Mod loader for Unity games. Through runtime injection it loads Mod DLLs into the game process and handles:</p><ul><li>Discovering all Mods under the <code>Mods/</code> directory</li><li>Identifying each Mod via its <code>Info.json</code></li><li>Enabling / disabling Mods (via <code>OnToggle</code>)</li><li>Providing a settings panel (<code>Ctrl+F10</code>)</li><li>Logging and displaying Mod logs</li></ul><h2 id="mod-directory-structure" tabindex="-1">Mod Directory Structure <a class="header-anchor" href="#mod-directory-structure" aria-label="Permalink to &quot;Mod Directory Structure&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ADOFAI/</span></span>
<span class="line"><span>├── Mods/</span></span>
<span class="line"><span>│   └── MyFirstMod/            # one folder per Mod</span></span>
<span class="line"><span>│       ├── MyFirstMod.dll     # compiled output</span></span>
<span class="line"><span>│       └── Info.json          # manifest file</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><blockquote><p>UMM identifies a Mod by the combination of &quot;folder name / <code>Info.json</code> / DLL&quot;. All three are required.</p></blockquote><h2 id="how-umm-loads-a-mod" tabindex="-1">How UMM Loads a Mod <a class="header-anchor" href="#how-umm-loads-a-mod" aria-label="Permalink to &quot;How UMM Loads a Mod&quot;">​</a></h2><ol><li>UMM scans every folder under <code>Mods/</code></li><li>Reads <code>Info.json</code> and finds <code>EntryMethod</code> (e.g. <code>MyFirstMod.Main.Load</code>)</li><li>Invokes the static <code>Load(UnityModManager.ModEntry)</code> method via reflection</li><li><code>Load</code> returning <code>true</code> means success; returning <code>false</code> marks the Mod as failed</li><li>When the player enables the Mod, UMM calls <code>OnToggle(entry, true)</code></li></ol><h2 id="modentry-your-interface-to-umm" tabindex="-1">ModEntry: Your Interface to UMM <a class="header-anchor" href="#modentry-your-interface-to-umm" aria-label="Permalink to &quot;ModEntry: Your Interface to UMM&quot;">​</a></h2><p><code>ModEntry</code> is the &quot;liaison object&quot; UMM hands to you; frequently used members:</p><table tabindex="0"><thead><tr><th>Member</th><th>Description</th></tr></thead><tbody><tr><td><code>Info</code></td><td>Parsed <code>Info.json</code> (Id, Version, Author, etc.)</td></tr><tr><td><code>Logger.Log(msg)</code></td><td>Log a message to the UMM interface</td></tr><tr><td><code>OnToggle</code></td><td>Enable/disable callback; the Mod&#39;s on/off logic goes here</td></tr><tr><td><code>OnGUI</code></td><td>Settings panel drawing callback</td></tr><tr><td><code>OnSaveGUI</code></td><td>Settings saving callback</td></tr><tr><td><code>Path</code></td><td>The Mod&#39;s on-disk directory (for configs, resources)</td></tr><tr><td><code>Error(msg)</code></td><td>Log an error and mark the Mod as failed</td></tr></tbody></table><h2 id="where-the-logs-go" tabindex="-1">Where the Logs Go <a class="header-anchor" href="#where-the-logs-go" aria-label="Permalink to &quot;Where the Logs Go&quot;">​</a></h2><ul><li>Press <code>Ctrl+F10</code> in game to open the UMM interface; logs are visible at the bottom right</li><li>Both <code>Logger.Log</code> and <code>Debug.Log</code> end up in the game log file</li><li>On Windows the game log lives at <code>%APPDATA%\\..\\LocalLow\\7th Beat Games\\A Dance of Fire and Ice\\Player.log</code></li></ul><h2 id="what-you-learned" tabindex="-1">What You Learned <a class="header-anchor" href="#what-you-learned" aria-label="Permalink to &quot;What You Learned&quot;">​</a></h2><ul><li>How UMM discovers and loads Mods</li><li>The Mod directory structure and the role of <code>Info.json</code></li><li>What interfaces <code>ModEntry</code> provides</li><li>Where to find logs</li></ul><h2 id="next-step" tabindex="-1">Next Step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next Step&quot;">​</a></h2><p>Write a minimal loadable Mod from the template → <a href="./first-mod">Minimal Example</a></p>`,19)])])}const p=o(n,[["render",r]]);export{m as __pageData,p as default};
